/**
 * Region masks come from the static assets (generated by tools/build-regions.ts),
 * so the Worker never generates the world. Decoded masks are kept per isolate.
 */
import { decodeMask, type RegionMask } from '../src/game/rules.ts';
import type { RegionMaskDTO } from '../src/game/types.ts';
import { ApiFail } from './http.ts';
import type { Env } from './env.ts';

const cache = new Map<number, RegionMask>();
const MAX = 256;
let indexCache: { count: number } | null = null;

function assetUrl(env: Env, path: string): URL {
  return new URL(path, env.PUBLIC_URL || 'https://terria.local');
}

export async function regionMask(env: Env, id: number): Promise<RegionMask> {
  const hit = cache.get(id);
  if (hit) {
    cache.delete(id);
    cache.set(id, hit);
    return hit;
  }
  const res = await env.ASSETS.fetch(assetUrl(env, `/regions/${id}.json`));
  if (!res.ok) throw new ApiFail(500, 'internal', `region ${id} mask missing`);
  const mask = decodeMask((await res.json()) as RegionMaskDTO);
  cache.set(id, mask);
  if (cache.size > MAX) cache.delete(cache.keys().next().value as number);
  return mask;
}

export async function regionCount(env: Env): Promise<number> {
  if (indexCache) return indexCache.count;
  const res = await env.ASSETS.fetch(assetUrl(env, '/regions/index.json'));
  if (!res.ok) throw new ApiFail(500, 'internal', 'region index missing');
  const idx = (await res.json()) as { count: number };
  indexCache = { count: idx.count };
  return idx.count;
}
